// Package corpus loads the parser-evaluation fixture corpus (issue #29)
// and funnels fixture bytes into the parser ONLY through the existing
// trust boundary: manifest sha256 check, then admission.Validate, then
// parser.NewTrustedDocument. There is no bypass path by construction:
// LoadTrustedDocument is the sole sanctioned route from fixture to parser
// input, and integrity is verified BEFORE admission is consulted.
//
// Expected on-disk layout (generated by a sibling agent):
//
//	<fixturesRoot>/manifest.yaml
//	<fixturesRoot>/v1/CASE-XXX/document.pdf
//	<fixturesRoot>/v1/CASE-XXX/expected.json
//	<fixturesRoot>/v1/CASE-XXX/metadata.yaml
//
// YAML choice: stdlib-only. go.mod carries no YAML dependency and the
// manifest/metadata schemas are flat scalars plus one small string list,
// so this package parses that minimal subset by hand (below) instead of
// adding gopkg.in/yaml.v3.
package corpus

import (
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"strings"
)

// manifestFileName is the manifest file expected at the fixtures root.
const manifestFileName = "manifest.yaml"

// metadataFileName is the per-case sidecar file expected next to each PDF.
const metadataFileName = "metadata.yaml"

// Case is one corpus entry. ID, PDFPath and SHA256 come from manifest.yaml
// (the integrity source of truth); the descriptive fields are enriched
// from the case metadata.yaml when present.
type Case struct {
	ID                 string
	DocumentType       string
	Difficulty         string
	SourceType         string
	Seed               string
	PIIStatus          string
	License            string
	ExpectedFields     []string
	ExpectedTables     bool
	ExpectedProvenance string
	PDFPath            string
	SHA256             string
}

// Dir returns the case directory holding document.pdf, expected.json and
// metadata.yaml.
func (c Case) Dir() string { return filepath.Dir(c.PDFPath) }

// Manifest is the parsed fixtures-root manifest: version plus one entry
// per case, in manifest order (deterministic).
type Manifest struct {
	Version string
	Cases   []Case
}

// LoadManifest parses <fixturesRoot>/manifest.yaml and enriches each entry
// from its case metadata.yaml (best-effort: a missing metadata.yaml leaves
// the manifest-only fields; a present but contradictory one is an error).
func LoadManifest(fixturesRoot string) (Manifest, error) {
	raw, err := os.ReadFile(filepath.Join(fixturesRoot, manifestFileName))
	if err != nil {
		return Manifest{}, fmt.Errorf("corpus: read manifest: %w", err)
	}
	entries, version, err := parseManifest(raw)
	if err != nil {
		return Manifest{}, err
	}
	m := Manifest{Version: version}
	seenID := make(map[string]bool, len(entries))
	seenPath := make(map[string]bool, len(entries))
	for i, e := range entries {
		c := Case{
			ID:           e["case_id"],
			DocumentType: e["document_type"],
			Difficulty:   e["difficulty"],
		}
		if c.ID == "" {
			return Manifest{}, fmt.Errorf("corpus: manifest entry %d: missing required key %q", i, "case_id")
		}
		rel := e["path"]
		if rel == "" {
			// Derived layout: v1/{case_id}/document.pdf (the generator
			// contract). Explicit path wins when present.
			rel = filepath.Join("v1", c.ID, "document.pdf")
		}
		if e["sha256"] == "" {
			return Manifest{}, fmt.Errorf("corpus: manifest entry %s: missing required key %q", c.ID, "sha256")
		}
		if !isHex64(e["sha256"]) {
			return Manifest{}, fmt.Errorf("corpus: manifest entry %s: sha256 must be 64 hex chars", c.ID)
		}
		c.SHA256 = strings.ToLower(e["sha256"])
		clean := filepath.Clean(rel)
		if filepath.IsAbs(clean) || hasDotDotSegment(clean) {
			return Manifest{}, fmt.Errorf("corpus: manifest entry %s: path %q escapes fixtures root", c.ID, rel)
		}
		c.PDFPath = filepath.Join(fixturesRoot, clean)
		if seenID[c.ID] {
			return Manifest{}, fmt.Errorf("corpus: manifest entry %s: duplicate case_id", c.ID)
		}
		if seenPath[c.PDFPath] {
			return Manifest{}, fmt.Errorf("corpus: manifest entry %s: duplicate path %q", c.ID, rel)
		}
		seenID[c.ID] = true
		seenPath[c.PDFPath] = true
		if err := enrichFromMetadata(&c); err != nil {
			return Manifest{}, err
		}
		m.Cases = append(m.Cases, c)
	}
	if len(m.Cases) == 0 {
		return Manifest{}, errors.New("corpus: manifest lists zero cases")
	}
	return m, nil
}

// enrichFromMetadata fills the descriptive Case fields from the case
// metadata.yaml. A missing file is tolerated (manifest-only case); a
// present file whose case_id/document_type/difficulty contradict the
// manifest is a hard error so sibling drift fails fast.
func enrichFromMetadata(c *Case) error {
	data, err := os.ReadFile(filepath.Join(c.Dir(), metadataFileName))
	if err != nil {
		if errors.Is(err, os.ErrNotExist) {
			return nil
		}
		return fmt.Errorf("corpus: case %s: read metadata: %w", c.ID, err)
	}
	meta, err := parseMetadata(data)
	if err != nil {
		return fmt.Errorf("corpus: case %s: %w", c.ID, err)
	}
	if meta.caseID != "" && meta.caseID != c.ID {
		return fmt.Errorf("corpus: case %s: metadata case_id %q does not match manifest", c.ID, meta.caseID)
	}
	if meta.documentType != "" && c.DocumentType != "" && meta.documentType != c.DocumentType {
		return fmt.Errorf("corpus: case %s: metadata document_type %q contradicts manifest %q", c.ID, meta.documentType, c.DocumentType)
	}
	if meta.difficulty != "" && c.Difficulty != "" && meta.difficulty != c.Difficulty {
		return fmt.Errorf("corpus: case %s: metadata difficulty %q contradicts manifest %q", c.ID, meta.difficulty, c.Difficulty)
	}
	if c.DocumentType == "" {
		c.DocumentType = meta.documentType
	}
	if c.Difficulty == "" {
		c.Difficulty = meta.difficulty
	}
	c.SourceType = meta.sourceType
	c.Seed = meta.seed
	c.PIIStatus = meta.piiStatus
	c.License = meta.license
	c.ExpectedFields = meta.expectedFields
	c.ExpectedTables = meta.expectedTables
	c.ExpectedProvenance = meta.expectedProvenance
	return nil
}

// ---------------------------------------------------------------------------
// Minimal YAML subset parser.
//
// Supported: flat `key: value` scalars, a top-level block sequence of maps
// (`cases:` followed by indented `- k: v` items with `k: v` continuations),
// block string lists (`key:` followed by indented `- item` lines), flow
// lists (`key: [a, b]`), `#` comments, and single/double-quoted scalars.
// Rejected: tabs for indentation, nested maps, multiline block scalars,
// anchors, and (for expected_fields items) commas inside quoted entries.
// Unknown keys are ignored for forward compatibility.
// ---------------------------------------------------------------------------

type yline struct {
	no     int
	indent int
	text   string
}

func splitLines(data []byte) ([]yline, error) {
	raw := strings.Split(string(data), "\n")
	out := make([]yline, 0, len(raw))
	for i, line := range raw {
		line = strings.TrimSuffix(line, "\r")
		if strings.HasPrefix(line, "\t") {
			return nil, fmt.Errorf("corpus: yaml line %d: tabs not allowed for indentation", i+1)
		}
		code := stripComment(line)
		indent := 0
		for indent < len(code) && code[indent] == ' ' {
			indent++
		}
		out = append(out, yline{no: i + 1, indent: indent, text: strings.TrimSpace(code)})
	}
	return out, nil
}

// stripComment cuts a `#` comment that starts the line or follows a space,
// unless the `#` sits inside single or double quotes.
func stripComment(line string) string {
	var inSingle, inDouble bool
	for i := 0; i < len(line); i++ {
		switch c := line[i]; {
		case c == '\'' && !inDouble:
			inSingle = !inSingle
		case c == '"' && !inSingle:
			inDouble = !inDouble
		case c == '#' && !inSingle && !inDouble && (i == 0 || line[i-1] == ' ' || line[i-1] == '\t'):
			return line[:i]
		}
	}
	return line
}

// splitKV splits `key: value` on the first colon. A colon not followed by
// space/tab/EOL is not a mapping (e.g. `http://...`), mirroring YAML.
func splitKV(s string) (key, value string, ok bool) {
	idx := strings.IndexByte(s, ':')
	if idx < 0 {
		return "", "", false
	}
	if idx+1 < len(s) && s[idx+1] != ' ' && s[idx+1] != '\t' {
		return "", "", false
	}
	key = strings.TrimSpace(s[:idx])
	if key == "" {
		return "", "", false
	}
	return key, strings.TrimSpace(s[idx+1:]), true
}

// unquote trims surrounding whitespace and one layer of matching quotes.
// No escape processing: corpus values are simple tokens.
func unquote(s string) string {
	s = strings.TrimSpace(s)
	if len(s) >= 2 {
		if (s[0] == '"' && s[len(s)-1] == '"') || (s[0] == '\'' && s[len(s)-1] == '\'') {
			return s[1 : len(s)-1]
		}
	}
	return s
}

func isHex64(s string) bool {
	if len(s) != 64 {
		return false
	}
	for i := 0; i < len(s); i++ {
		c := s[i]
		if !(c >= '0' && c <= '9' || c >= 'a' && c <= 'f' || c >= 'A' && c <= 'F') {
			return false
		}
	}
	return true
}

func hasDotDotSegment(clean string) bool {
	for _, seg := range strings.Split(clean, string(filepath.Separator)) {
		if seg == ".." {
			return true
		}
	}
	return false
}

// parseManifest parses the manifest.yaml subset: optional top-level
// `version` (defaults to "1") and `case_count` (validated when present),
// plus a `cases:` block sequence of maps. Entry keys: case_id and sha256
// are required; path is optional and derived as v1/{case_id}/document.pdf
// when absent; document_type/difficulty ride along when present; nested
// lists (e.g. files:) are skipped via indent tracking; all other keys are
// ignored for forward compatibility.
func parseManifest(data []byte) ([]map[string]string, string, error) {
	lines, err := splitLines(data)
	if err != nil {
		return nil, "", err
	}
	version := ""
	expectCount := -1
	var entries []map[string]string
	var cur map[string]string
	entryIndent := -1
	inCases := false
	for _, ln := range lines {
		if ln.text == "" {
			continue
		}
		if ln.indent == 0 && !strings.HasPrefix(ln.text, "- ") && ln.text != "-" {
			inCases = false
			cur = nil
			entryIndent = -1
			k, v, ok := splitKV(ln.text)
			if !ok {
				return nil, "", fmt.Errorf("corpus: manifest line %d: expected \"key: value\", got %q", ln.no, ln.text)
			}
			switch k {
			case "version":
				version = unquote(v)
			case "case_count":
				n := 0
				for i := 0; i < len(unquote(v)); i++ {
					c := unquote(v)[i]
					if c < '0' || c > '9' {
						return nil, "", fmt.Errorf("corpus: manifest line %d: case_count must be a non-negative integer", ln.no)
					}
					n = n*10 + int(c-'0')
				}
				expectCount = n
			case "cases":
				if v != "" && v != "[]" {
					return nil, "", fmt.Errorf("corpus: manifest line %d: \"cases\" must be a block list", ln.no)
				}
				inCases = true
			default:
				// Ignore unknown top-level keys (forward compatibility).
			}
			continue
		}
		if !inCases {
			return nil, "", fmt.Errorf("corpus: manifest line %d: unexpected indented content outside \"cases:\"", ln.no)
		}
		if strings.HasPrefix(ln.text, "- ") || ln.text == "-" {
			if cur != nil && ln.indent > entryIndent {
				continue // nested list item (e.g. under files:); skip.
			}
			cur = make(map[string]string)
			entries = append(entries, cur)
			entryIndent = ln.indent
			if rest := strings.TrimSpace(strings.TrimPrefix(ln.text, "-")); rest != "" {
				k, v, ok := splitKV(rest)
				if !ok {
					return nil, "", fmt.Errorf("corpus: manifest line %d: expected \"key: value\", got %q", ln.no, rest)
				}
				cur[k] = unquote(v)
			}
			continue
		}
		if cur == nil {
			return nil, "", fmt.Errorf("corpus: manifest line %d: expected \"- \" list item", ln.no)
		}
		if ln.indent <= entryIndent {
			return nil, "", fmt.Errorf("corpus: manifest line %d: expected deeper indent under list item, got %q", ln.no, ln.text)
		}
		k, v, ok := splitKV(ln.text)
		if !ok {
			return nil, "", fmt.Errorf("corpus: manifest line %d: expected \"key: value\", got %q", ln.no, ln.text)
		}
		cur[k] = unquote(v)
	}
	if version == "" {
		version = "1"
	}
	if expectCount >= 0 && len(entries) != expectCount {
		return nil, "", fmt.Errorf("corpus: manifest case_count = %d, want %d entries", expectCount, len(entries))
	}
	return entries, version, nil
}

type rawMetadata struct {
	caseID             string
	documentType       string
	difficulty         string
	sourceType         string
	seed               string
	piiStatus          string
	license            string
	expectedProvenance string
	expectedFields     []string
	expectedTables     bool
}

// parseMetadata parses the flat metadata.yaml subset plus the
// expected_fields string list (block or flow style).
func parseMetadata(data []byte) (rawMetadata, error) {
	var m rawMetadata
	lines, err := splitLines(data)
	if err != nil {
		return m, err
	}
	inList := false
	for _, ln := range lines {
		if ln.text == "" {
			continue
		}
		if strings.HasPrefix(ln.text, "- ") || ln.text == "-" {
			// Block-list item (the generator emits items at indent 0).
			if !inList {
				return m, fmt.Errorf("metadata line %d: unexpected list item outside expected_fields", ln.no)
			}
			if item := unquote(strings.TrimSpace(strings.TrimPrefix(ln.text, "-"))); item == "" {
				return m, fmt.Errorf("metadata line %d: empty item in expected_fields list", ln.no)
			} else {
				m.expectedFields = append(m.expectedFields, item)
			}
			continue
		}
		if ln.indent == 0 {
			inList = false
			k, v, ok := splitKV(ln.text)
			if !ok {
				return m, fmt.Errorf("metadata line %d: expected \"key: value\", got %q", ln.no, ln.text)
			}
			switch k {
			case "case_id":
				m.caseID = unquote(v)
			case "document_type":
				m.documentType = unquote(v)
			case "difficulty":
				m.difficulty = unquote(v)
			case "source_type":
				m.sourceType = unquote(v)
			case "synthetic_seed":
				m.seed = unquote(v)
			case "pii_status":
				m.piiStatus = unquote(v)
			case "license":
				m.license = unquote(v)
			case "expected_provenance":
				m.expectedProvenance = unquote(v)
			case "expected_tables":
				b, err := parseBool(v)
				if err != nil {
					return m, fmt.Errorf("metadata line %d: %w", ln.no, err)
				}
				m.expectedTables = b
			case "expected_fields":
				switch {
				case v == "" || v == "[]":
					m.expectedFields = []string{}
					inList = v == ""
				case strings.HasPrefix(v, "["):
					fields, err := parseFlowList(v)
					if err != nil {
						return m, fmt.Errorf("metadata line %d: %w", ln.no, err)
					}
					m.expectedFields = fields
				default:
					m.expectedFields = []string{unquote(v)}
				}
			default:
				// Ignore unknown keys (forward compatibility).
			}
			continue
		}
		if ln.indent > 0 {
			return m, fmt.Errorf("metadata line %d: unexpected indented content %q", ln.no, ln.text)
		}
		return m, fmt.Errorf("metadata line %d: expected \"key: value\", got %q", ln.no, ln.text)
	}
	return m, nil
}

func parseBool(v string) (bool, error) {
	switch strings.ToLower(unquote(v)) {
	case "true":
		return true, nil
	case "false":
		return false, nil
	default:
		return false, fmt.Errorf("expected true/false, got %q", v)
	}
}

func parseFlowList(v string) ([]string, error) {
	if !strings.HasPrefix(v, "[") || !strings.HasSuffix(v, "]") {
		return nil, fmt.Errorf("malformed flow list %q", v)
	}
	inner := strings.TrimSpace(v[1 : len(v)-1])
	if inner == "" {
		return []string{}, nil
	}
	parts := strings.Split(inner, ",")
	out := make([]string, 0, len(parts))
	for _, p := range parts {
		if item := unquote(p); item == "" {
			return nil, fmt.Errorf("empty item in flow list %q", v)
		} else {
			out = append(out, item)
		}
	}
	return out, nil
}
